def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"c": []}) == 0.0


def test_trailing_window_boundaries():
    counts = [3, 1, 2]
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 2) == 3
    assert flags_in_window(counts, 4) == 6


def test_longest_streak_resets_on_nonpositive_counts():
    assert longest_flag_streak([1, 3, 0, 1, -1, 2, 1, 1]) == 3
    assert longest_flag_streak([]) == 0


def test_group_rates_and_ranking():
    groups = {"c": [{"flagged": False}], "z": [], "b": [{"flagged": True}], "a": [{"flagged": True}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", 1.0), ("c", 0.0), ("z", None)]
    assert top_flagged_groups(groups, 4) == ["a", "b", "c"]
    assert top_flagged_groups(groups, 1) == ["a"]


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"g": parse_transcript_log(["a,1,1", "b,1,0", "c,4,0"]), "empty": []}
    assert monitor_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 1}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}
